public class Main {
    interface BeanPostProcessor {
        Object postBefore(Object b, String n);
        Object postAfter(Object b, String n);
    }

    static class LogBPP implements BeanPostProcessor {
        public Object postBefore(Object b, String n) { System.out.println("[BPP] before " + n); return b; }
        public Object postAfter(Object b, String n) { System.out.println("[BPP] after " + n); return b; }
    }

    static class Bean { String name() { return "bean"; } }

    public static void main(String[] args) {
        Bean b = new Bean();
        BeanPostProcessor bpp = new LogBPP();
        Object x = bpp.postBefore(b, "bean");
        Object y = bpp.postAfter(x, "bean");
        System.out.println("processed: " + (y == b));
    }
}
